def cases_by_difficulty(*diffs: str) -> tuple[T3Case, ...]:
    """按难度过滤（CI 门禁取 ◆/◇；★ 留给 T4 nightly 探针池）。"""
    return tuple(c for c in CORPUS if c.difficulty in diffs)


def category_counts() -> dict[str, int]:
    counts: dict[str, int] = {}
    for c in CORPUS:
        counts[c.category] = counts.get(c.category, 0) + 1
    return counts
